const products=[{id:'dog',name:'The Everyday Dog Bowl',category:'Dog food',detail:'Chicken & vegetables · 3 kg',price:34.9,color:'#a15938',type:'bag',tag:'Bowl-time favourite',label:'EVERYDAY DOG',flavour:'CHICKEN + VEGETABLES',animal:'🐕'},{id:'cat',name:'The Happy Cat Crunch',category:'Cat food',detail:'Salmon & chicken · 1.5 kg',price:26.9,color:'#647858',type:'bag',tag:'For little foodies',label:'HAPPY CAT',flavour:'SALMON + CHICKEN',animal:'🐈'},{id:'rope',name:'The Tug & Toss Rope',category:'Toys',detail:'Cotton rope · Terracotta',price:14.9,type:'rope',tag:'Playtime pick'},{id:'mouse',name:'The Little Pounce Mouse',category:'Toys',detail:'Soft mouse toy · 2 pack',price:9.9,type:'mouse',tag:'Chase. Pounce. Repeat.'}];
let category='All',cart={};try{cart=JSON.parse(localStorage.getItem('marys-cart'))||{};for(const [id,qty]of Object.entries(cart)){if(!products.some(p=>p.id===id)||!Number.isInteger(qty)||qty<1||qty>99)delete cart[id]}}catch{cart={}}
const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD'}).format(n);const grid=document.querySelector('#products');
function illustration(p){if(p.type==='bag')return `<div class="bag-art" style="--bag-color:${p.color}"><div class="bag-logo">mary’s</div><small>GOOD FOOD. HAPPY PETS.</small><div class="bag-animal">${p.animal}</div><div class="bag-title">${p.label}</div><div class="bag-flavour">${p.flavour}</div></div>`;if(p.type==='rope')return '<svg width="170" height="170" viewBox="0 0 170 170" aria-hidden="true"><defs><pattern id="rope" width="9" height="9" patternUnits="userSpaceOnUse" patternTransform="rotate(35)"><rect width="9" height="9" fill="#d47b4f"/><path d="M0 0V9" stroke="#f4bd88" stroke-width="4"/></pattern></defs><g transform="rotate(-30 85 85)" stroke="url(#rope)" fill="none" stroke-width="19"><path d="M55 46C8 7 10 111 55 86L120 58C170 33 166 137 118 105Z"/><path d="M36 64 18 72M38 75 18 91M135 76 157 63M138 88 162 88" stroke-width="8"/></g></svg>';return '<svg width="170" height="170" viewBox="0 0 170 170" aria-hidden="true"><path d="M109 105q60 25 41-30" fill="none" stroke="#ca987f" stroke-width="5"/><ellipse cx="80" cy="94" rx="43" ry="29" fill="#b2b29c" transform="rotate(-20 80 94)"/><circle cx="70" cy="65" r="17" fill="#a6a58f"/><circle cx="70" cy="65" r="11" fill="#dec5b3"/><circle cx="44" cy="95" r="3" fill="#253b2d"/><circle cx="34" cy="106" r="5" fill="#ca987f"/><path d="m44 108-20 5m21 0-15 10" stroke="#757762" stroke-width="1.5"/></svg>'}
function renderProducts(){const term=document.querySelector('#search').value.toLowerCase();const list=products.filter(p=>(category==='All'||p.category===category)&&(p.name+' '+p.detail+' '+p.category).toLowerCase().includes(term));grid.innerHTML=list.map(p=>`<article class="product"><div class="product-image" style="background:${p.type==='mouse'?'#e8eadd':p.type==='rope'?'#f5e4d8':'#efeddf'}"><span class="tag">${p.tag}</span>${illustration(p)}</div><div class="product-type">${p.category.toUpperCase()}</div><h3>${p.name}</h3><p class="product-detail">${p.detail}</p><div class="product-bottom"><b>${money(p.price)}<small>NZD</small></b><button class="add-button" data-add="${p.id}" aria-label="Add ${p.name} to bag">+</button></div></article>`).join('')||'<p class="no-results">No little treasures found. Try another search.</p>';document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===category);b.setAttribute('aria-pressed',b.dataset.filter===category)})}
function syncCart(){try{localStorage.setItem('marys-cart',JSON.stringify(cart))}catch{}document.querySelector('#bag-count').textContent=Object.values(cart).reduce((a,b)=>a+b,0);document.querySelector('#cart-items').innerHTML=Object.keys(cart).length?products.filter(p=>cart[p.id]).map(p=>`<div class="cart-row"><div><div class="cart-row-name">${p.name}</div><small>${money(p.price)} each</small><div class="quantity"><button data-change="${p.id}" data-delta="-1" aria-label="Remove one ${p.name}">−</button><span>${cart[p.id]}</span><button data-change="${p.id}" data-delta="1" aria-label="Add one ${p.name}">+</button></div></div><b>${money(p.price*cart[p.id])}</b></div>`).join(''):'<p class="empty">Your bag is waiting for a little goodness.<br>Find their next favourite in the collection.</p>';document.querySelector('#cart-total').textContent=money(products.reduce((n,p)=>n+p.price*(cart[p.id]||0),0))}
let toastTimer;document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){cart[add.dataset.add]=Math.min((cart[add.dataset.add]||0)+1,99);syncCart();const toast=document.querySelector('#toast');toast.textContent='A little goodness added to your bag ♡';toast.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.classList.remove('show'),2400)}const filter=e.target.closest('[data-filter]');const link=e.target.closest('[data-category]');if(filter||link){category=(filter||link).dataset[filter?'filter':'category'];document.querySelector('#search').value='';renderProducts()}const change=e.target.closest('[data-change]');if(change){const id=change.dataset.change;cart[id]=Math.min(99,cart[id]+Number(change.dataset.delta));if(cart[id]<=0)delete cart[id];syncCart()}});
document.querySelector('#search').addEventListener('input',renderProducts);const dialog=document.querySelector('#cart');document.querySelector('.basket-button').onclick=()=>dialog.showModal();document.querySelector('#close-cart').onclick=()=>dialog.close();document.querySelector('#continue-shopping').onclick=()=>{dialog.close();document.querySelector('#shop').scrollIntoView({behavior:'smooth'})};dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});document.querySelector('.search-button').onclick=()=>{document.querySelector('#shop').scrollIntoView();document.querySelector('#search').focus({preventScroll:true})};document.querySelector('#year').textContent=new Date().getFullYear();renderProducts();syncCart();
